import { createAsyncThunk, createSlice } from "@reduxjs/toolkit";
import mobCountService from "../services/mobCountService";
import { uniqBy } from "lodash";

const initialState = {
  isError: false,
  isSuccess: false,
  isLoading: false,
  message: "",
  mobApplicationsCount: [],
  mobSurveysCount: [],
  mobDownPaymentsCount: [],
  mobContractsCount: [],
  mobSaleInvoicesCount: [],
  mobRemindersCount: [],
};

export const getMobApplicationsCount = createAsyncThunk(
  "mob/applicationsCount",
  async ({params}, thunkAPI) => {
    try {
      return await mobCountService.getMobApplicationsCount(params);
    } catch (error) {
      const message =
        (error.response &&
          error.response.data &&
          error.response.data.message) ||
        error.message ||
        error.toString();
      return thunkAPI.rejectWithValue(message);
    }
  }
);

export const getMobSurveysCount = createAsyncThunk(
  "mob/surveysCount",
  async (_, thunkAPI) => {
    try {
      return await mobCountService.getMobSurveysCount();
    } catch (error) {
      const message =
        (error.response &&
          error.response.data &&
          error.response.data.message) ||
